// Hand-written. NOT generated by CLI Printing Press - see handfixes.json,
// record `typed-resources-table-parent-prefixed`.
//
// Reader-side receipts for the `resources` typed-table rename. The store-side
// receipts live in cli/internal/store/typed_resources_table_test.go; these two
// concerns can only be pinned from this package:
//
//  1. `search --type resources` unions the typed index with the generic one and
//     dedups by RESOURCE ID. The union is load-bearing (a store synced by an
//     earlier binary has an empty typed table) and the id-keyed dedup is
//     load-bearing (the two copies of one record can legitimately diverge).
//  2. The `resources_bookings` fan-out reads the catch-all through a
//     resource_type filter and has never been able to see another type's ids.
//     This test exists to keep a correction honest: an earlier draft of this
//     change claimed the fan-out called ListIDs("resources") and was being
//     handed client and project ids. It never did and never was.

package cli

import (
	"encoding/json"
	"path/filepath"
	"strings"
	"testing"

	"resourceguru-pp-cli/internal/store"
)

func openTestStore(t *testing.T) *store.Store {
	t.Helper()
	s, err := store.Open(filepath.Join(t.TempDir(), "data.db"))
	if err != nil {
		t.Fatalf("open store: %v", err)
	}
	t.Cleanup(func() { s.Close() })
	return s
}

// TestSearchResourcesUnion_DedupsDivergedCopiesByResourceID pins the dedup key.
//
// UpsertBatch writes the generic catch-all row first and unconditionally, then
// attempts the typed projection inside a SAVEPOINT. A typed-table failure rolls
// the projection back to whatever it held before while the generic row keeps the
// new payload, so one resource id can be represented by two different JSON
// documents at once. A union deduped by raw JSON bytes returns BOTH - the same
// resource twice, the stale copy indistinguishable from a second resource.
//
// This test drives that divergence with the store's own API: UpsertBatch writes
// both copies, then Upsert writes the generic copy only (it calls
// upsertGenericResourceTx and nothing else), which is exactly the state a
// rolled-back savepoint leaves. The union must answer once, with the generic
// payload, because the generic row is the store's durable copy - it is what
// `list`, `get` and `sql` read.
func TestSearchResourcesUnion_DedupsDivergedCopiesByResourceID(t *testing.T) {
	db := openTestStore(t)
	const probe = "zqxjppresourceprobe"

	if _, _, err := db.UpsertBatch("resources", []json.RawMessage{
		json.RawMessage(`{"id":"res-1","name":"Ada Lovelace","notes":"` + probe + `"}`),
	}); err != nil {
		t.Fatalf("UpsertBatch: %v", err)
	}
	if err := db.Upsert("resources", "res-1",
		json.RawMessage(`{"id":"res-1","name":"Ada Byron","notes":"`+probe+`"}`)); err != nil {
		t.Fatalf("Upsert (generic only): %v", err)
	}

	// The divergence is real, or this test proves nothing: the typed index must
	// still be answering the OLD payload while the generic one answers the new.
	typed, err := db.SearchResources(probe, 10)
	if err != nil {
		t.Fatalf("SearchResources: %v", err)
	}
	if len(typed) != 1 || !strings.Contains(string(typed[0]), "Ada Lovelace") {
		t.Fatalf("typed index = %s, want the stale 'Ada Lovelace' copy; the divergence this test needs was not set up", typed)
	}
	generic, err := db.Search(probe, 10, "resources")
	if err != nil {
		t.Fatalf("generic Search: %v", err)
	}
	if len(generic) != 1 || !strings.Contains(string(generic[0]), "Ada Byron") {
		t.Fatalf("generic index = %s, want the fresh 'Ada Byron' copy", generic)
	}

	results, err := searchResourcesUnion(db, probe, 10)
	if err != nil {
		t.Fatalf("searchResourcesUnion: %v", err)
	}
	if len(results) != 1 {
		t.Fatalf("searchResourcesUnion returned %d rows for one resource id: %s; the union deduped on raw JSON bytes, not on the id", len(results), results)
	}
	if !strings.Contains(string(results[0]), "Ada Byron") {
		t.Fatalf("searchResourcesUnion returned %s, want the generic copy 'Ada Byron' (the durable row wins over a stale typed projection)", results[0])
	}
}

// TestSearchResourcesUnion_AnswersPreResyncStoresFromTheGenericIndex is why the
// union exists at all, and why the ledger asserts on searchResourcesUnion by
// name. A store synced by resourceguru-v0.1.0 or v0.1.1 has every resource in
// the catch-all and an EMPTY typed table until the operator re-syncs. A reprint
// that restored the plain `db.SearchResources(query, limit)` call would compile,
// pass every generated test, and answer zero rows for the connector's headline
// resource on every such store.
func TestSearchResourcesUnion_AnswersPreResyncStoresFromTheGenericIndex(t *testing.T) {
	db := openTestStore(t)
	const probe = "zqxjppresourceprobe"

	// Upsert writes the generic row and the generic FTS entry only, which is the
	// pre-resync state: catch-all populated, typed projection empty.
	if err := db.Upsert("resources", "res-1",
		json.RawMessage(`{"id":"res-1","name":"Ada Lovelace","notes":"`+probe+`"}`)); err != nil {
		t.Fatalf("Upsert: %v", err)
	}
	var typedRows int
	if err := db.DB().QueryRow(`SELECT COUNT(*) FROM "accounts_resources"`).Scan(&typedRows); err != nil {
		t.Fatalf("count typed projection: %v", err)
	}
	if typedRows != 0 {
		t.Fatalf("typed projection holds %d rows; this test needs the pre-resync state", typedRows)
	}

	results, err := searchResourcesUnion(db, probe, 10)
	if err != nil {
		t.Fatalf("searchResourcesUnion: %v", err)
	}
	if len(results) != 1 || !strings.Contains(string(results[0]), "Ada Lovelace") {
		t.Fatalf("searchResourcesUnion on a pre-resync store returned %s, want the catch-all row; a typed-only query answers zero here", results)
	}
}

// TestDependentParentRows_ResourcesFanOutIsTypeFiltered is a correction receipt.
//
// An earlier draft of this change claimed that the `resources_bookings`
// dependent fan-out called ListIDs("resources"), that a bare `resources`
// resolved to the catch-all, and that the fan-out was therefore being handed
// client, project and booking ids and fetching
// /v1/{account}/resources/{id}/bookings for each. That is false, and this test
// is what makes the correction checkable rather than a claim in a CHANGELOG.
//
// The declaration is
// {Name: "resources_bookings", ParentTable: "resources", PathParams: [{account,
// v1_id}, {id, id}]}. Two path params means dependentParentFields returns
// ["id", "v1_id"], which is neither the single-field branch (ListIDsScoped) nor
// the one-path-param branch (ListField), so dependentParentRows routes to
// ListFieldSets - and ListFieldSets reads the catch-all directly under
// `WHERE resource_type = ?`. There is no resource-type-to-table resolve on that
// path, so there has never been a way for another type's rows to reach it.
//
// Two assertions, and both matter:
//
//   - Seeding ONLY the catch-all (typed projection left empty) and still getting
//     the resource row back proves the fan-out does not read the typed table.
//     That is what identifies the route as ListFieldSets; a ListIDs route would
//     answer zero here now that typedTableName points it at the typed table.
//   - A client row carrying the same fields is excluded, proving the
//     resource_type filter that made the claimed contamination impossible.
func TestDependentParentRows_ResourcesFanOutIsTypeFiltered(t *testing.T) {
	db := openTestStore(t)

	var dep dependentResourceDef
	for _, candidate := range dependentResourceDefs() {
		if candidate.Name == "resources_bookings" {
			dep = candidate
			break
		}
	}
	if dep.Name == "" {
		t.Fatal("no resources_bookings dependent declaration; this connector's fan-out shape changed and this receipt needs rewriting")
	}
	if dep.ParentTable != "resources" {
		t.Fatalf("resources_bookings parent table = %q, want \"resources\"", dep.ParentTable)
	}

	// Seed the CATCH-ALL only, via Upsert, which writes no typed row.
	if err := db.Upsert("resources", "res-1",
		json.RawMessage(`{"id":"res-1","v1_id":"acct-A","name":"Ada Lovelace"}`)); err != nil {
		t.Fatalf("seed resource row: %v", err)
	}
	if err := db.Upsert("clients", "client-1",
		json.RawMessage(`{"id":"client-1","v1_id":"acct-A","name":"Acme"}`)); err != nil {
		t.Fatalf("seed client row: %v", err)
	}
	var typedRows int
	if err := db.DB().QueryRow(`SELECT COUNT(*) FROM "accounts_resources"`).Scan(&typedRows); err != nil {
		t.Fatalf("count typed projection: %v", err)
	}
	if typedRows != 0 {
		t.Fatalf("typed projection holds %d rows; this test needs it empty to identify the route", typedRows)
	}

	rows, err := dependentParentRows(db, dep.ParentTable, dep.PathParams, "", "")
	if err != nil {
		t.Fatalf("dependentParentRows: %v", err)
	}
	if len(rows) != 1 {
		t.Fatalf("resources_bookings fan-out enumerated %v (%d parents), want exactly the 1 resource row; more than one means the resource_type filter is gone, zero means the route now reads the typed table", rows, len(rows))
	}
	if rows[0]["id"] != "res-1" || rows[0]["v1_id"] != "acct-A" {
		t.Fatalf("fan-out parent row = %v, want id=res-1 v1_id=acct-A", rows[0])
	}
}
